"""Render top view of a plate generated by layout2openscad as SVG image.

Supports subset of OpenSCAD used by layout2openscad output: polygon,
linear_extrude, cube, translate, rotate (around Z axis), union and difference.
Geometry is projected on XY plane, so cuts are assumed to go through the plate.
Uses shapely, run in 'tools-openscad' hatch environment.
"""

import argparse
import re
from typing import Any, List, Tuple

import shapely
from shapely import affinity
from shapely.geometry.base import BaseGeometry

TOKEN = re.compile(
    r"\s*(?:(?P<number>-?\d+(?:\.\d*)?(?:[eE][-+]?\d+)?)"
    r"|(?P<name>\$?[A-Za-z_]\w*)|(?P<string>\"[^\"]*\")|(?P<symbol>[()\[\]{},;=?:]))"
)


class Node:
    def __init__(self, name: str, args: List[Any], kwargs: dict) -> None:
        self.name = name
        self.args = args
        self.kwargs = kwargs
        self.children: List[Node] = []


def _tokenize(source: str) -> List[Tuple[str, str]]:
    source = re.sub(r"/\*.*?\*/", "", source, flags=re.DOTALL)
    source = re.sub(r"//[^\n]*", "", source)
    tokens = []
    pos = 0
    while pos < len(source):
        if source[pos:].strip() == "":
            break
        match = TOKEN.match(source, pos)
        if not match:
            msg = f"Unexpected input at {pos}: '{source[pos:pos + 20]}'"
            raise ValueError(msg)
        kind = match.lastgroup
        assert kind
        tokens.append((kind, match.group(kind)))
        pos = match.end()
    return tokens


class Parser:
    def __init__(self, source: str) -> None:
        self.tokens = _tokenize(source)
        self.pos = 0

    def peek(self) -> Tuple[str, str]:
        if self.pos < len(self.tokens):
            return self.tokens[self.pos]
        return ("eof", "")

    def take(self, expected: str = "") -> str:
        kind, value = self.peek()
        if expected and value != expected:
            msg = f"Expected '{expected}', got '{value}'"
            raise ValueError(msg)
        self.pos += 1
        return value

    def value(self) -> Any:
        kind, value = self.peek()
        if value == "[":
            self.take("[")
            items = []
            while self.peek()[1] != "]":
                items.append(self.value())
                if self.peek()[1] == ",":
                    self.take(",")
            self.take("]")
            return items
        self.take()
        if kind == "number":
            return float(value)
        if value in ("true", "false"):
            return value == "true"
        return value

    def statements(self) -> List[Node]:
        nodes = []
        while self.peek()[0] != "eof" and self.peek()[1] != "}":
            if self.peek()[1] == ";":
                self.take(";")
                continue
            name = self.take()
            if self.peek()[1] == "=":
                # top level assignment (like '$fn'), not affecting geometry
                while self.take() != ";":
                    pass
                continue
            nodes.append(self.module(name))
        return nodes

    def module(self, name: str) -> Node:
        args: List[Any] = []
        kwargs = {}
        self.take("(")
        while self.peek()[1] != ")":
            if self.tokens[self.pos + 1][1] == "=":
                key = self.take()
                self.take("=")
                kwargs[key] = self.value()
            else:
                args.append(self.value())
            if self.peek()[1] == ",":
                self.take(",")
        self.take(")")
        node = Node(name, args, kwargs)
        if self.peek()[1] == "{":
            self.take("{")
            node.children = self.statements()
            self.take("}")
        else:
            self.take(";")
        return node


def _arg(node: Node, name: str, index: int, default: Any = None) -> Any:
    if name in node.kwargs:
        return node.kwargs[name]
    if index < len(node.args):
        return node.args[index]
    return default


def _union(nodes: List[Node]) -> BaseGeometry:
    return shapely.union_all([evaluate(n) for n in nodes])


def evaluate(node: Node) -> BaseGeometry:
    if node.name == "polygon":
        return shapely.Polygon(_arg(node, "points", 0))
    if node.name == "cube":
        size = _arg(node, "size", 0, 1.0)
        x, y = (size, size) if isinstance(size, float) else size[0:2]
        if _arg(node, "center", 1, False):
            return shapely.box(-x / 2, -y / 2, x / 2, y / 2)
        return shapely.box(0, 0, x, y)
    if node.name == "translate":
        v = _arg(node, "v", 0)
        return affinity.translate(_union(node.children), v[0], v[1])
    if node.name == "rotate":
        a = _arg(node, "a", 0)
        if isinstance(a, list):
            if a[0] != 0 or a[1] != 0:
                msg = "Only rotation around Z axis is supported"
                raise ValueError(msg)
            a = a[2]
        return affinity.rotate(_union(node.children), a, origin=(0, 0))
    if node.name == "difference":
        if not node.children:
            return shapely.Polygon()
        first, *rest = node.children
        return evaluate(first).difference(_union(rest))
    if node.name in ("union", "linear_extrude", "group"):
        return _union(node.children)
    msg = f"Unsupported module '{node.name}'"
    raise ValueError(msg)


def to_svg(geometry: BaseGeometry, *, margin: float = 2, scale: float = 4) -> str:
    min_x, min_y, max_x, max_y = geometry.bounds
    min_x, min_y = min_x - margin, min_y - margin
    width, height = max_x - min_x + margin, max_y - min_y + margin
    # OpenSCAD Y axis points up, SVG Y axis points down
    flipped = affinity.scale(geometry, 1, -1, origin=(0, 0))
    path = flipped.svg(scale_factor=0.2, fill_color="#8a9bb0", opacity=1)
    return (
        '<svg xmlns="http://www.w3.org/2000/svg" '
        f'width="{width * scale:.0f}" height="{height * scale:.0f}" '
        f'viewBox="{min_x} {-max_y - margin} {width} {height}">'
        f"{path}</svg>\n"
    )


def render(scad_path: str, svg_path: str) -> None:
    with open(scad_path, "r") as f:
        nodes = Parser(f.read()).statements()
    geometry = shapely.union_all([evaluate(n) for n in nodes])
    with open(svg_path, "w") as f:
        f.write(to_svg(geometry))


if __name__ == "__main__":
    parser = argparse.ArgumentParser(description="Render OpenSCAD plate top view")
    parser.add_argument("-i", "--in", required=True, help="OpenSCAD file")
    parser.add_argument("-o", "--out", required=True, help="Output SVG path")
    args = parser.parse_args()
    render(getattr(args, "in"), args.out)
